mapper.select:
select  from play_team
where invite_code = #{inviteCode}
   or (legacy_invite_code = #{inviteCode}
       and (legacy_invite_expire_time is null or legacy_invite_expire_time > now()))
limit 1 for update

mapper.update:
update play_team set invite_code = #{inviteCode}, update_time = now()
where id = #{teamId} and leader_member_id = #{leaderMemberId}
  and status in (0, 1)

mapper.select:
select count(distinct m.member_id)
from play_team_member m
where m.team_id = #{teamId} and m.status = 0 and m.apply_expire_time > #{now}

mapper.update:
update play_team_member
set status = #{toStatus}, update_time = now()
where team_id = #{teamId} and member_id = #{memberId} and status = #{fromStatus}

update play_team_member
set role = #{toRole}, update_time = now()
where team_id = #{teamId} and member_id = #{memberId} and status = 1 and role = #{fromRole}

mapper.select:
select count(1)
from cms_registration r
left join cms_activity a on r.owner_type = 2 and r.owner_id = a.id and a.del_flag = 0
where r.member_id = #{memberId}
  and r.payment_status = 2
  and r.registration_status = 2
  and (
    (r.owner_type = 1 and r.owner_id = #{topicId}
        and (r.expires_at is null or r.expires_at > now()))
    or (r.owner_type = 2 and a.topic_id = #{topicId}
        and (r.purchase_kind is null or r.purchase_kind <> 3
            or (a.cancel_time is null and a.end_date is not null and a.end_date > now())))
  )

mapper.update:
update play_team t
left join cms_activity activity on t.owner_type = 2 and activity.id = t.owner_id
left join cms_topic topic on topic.id = activity.topic_id
left join game_session game on t.owner_type = 2 and game.activity_id = t.owner_id
set t.status = 3, t.update_time = now()
where t.id = #{teamId}
  and t.status in (0, 1)
  and t.expire_time <= #{now}
  and (
    (game.id is null and topic.game_module_config_json is null)
    or activity.end_date <= #{now}
  )
